package com.telamin.fluxtion.runtime.audit;

/**
 * A target for a {@link LogRecord} generated by the {@link EventLogManager}. A
 * LogRecordListener is responsible for publishing the {@link LogRecord}.
 *
 * @author Greg Higgins (greg.higgins@v12technology.com)
 */
public interface LogRecordListener {

    void processLogRecord(LogRecord logRecord);

    /**
     * Receives the stream header, before the first record of each stream (see {@link AuditStreamHeader}).
     *
     * <p>The default delivers a TEXT stream's header as an ordinary record, so every text sink writes it with no
     * change: its {@code asCharSequence()} is one YAML document, {@code auditStreamHeader:}. A BINARY stream's
     * header is ignored by default, because a binary sink written before the header existed casts each record to
     * {@link BinaryLogRecord} and has no frame to write it in; {@link BinaryLogWriter} overrides this to write a
     * {@link BinaryLogFile#FRAME_STREAM_HEADER} frame. A sink that counts records and does not want the header
     * counted overrides this too.
     */
    default void processStreamHeader(StreamHeaderRecord header) {
        if (!header.isBinaryStream()) {
            processLogRecord(header);
        }
    }

    /**
     * A listener that forwards every record AND every header to each target, each target applying its own rule for a
     * header. Use it, not a lambda, to wrap or tee a {@link BinaryLogWriter}: a lambda inherits the default above, so
     * a binary stream's header never reaches the writer and the file carries no header frame.
     */
    static LogRecordListener forwardingTo(LogRecordListener... targets) {
        final LogRecordListener[] copy = targets.clone();
        return new LogRecordListener() {
            @Override
            public void processLogRecord(LogRecord logRecord) {
                for (LogRecordListener t : copy) {
                    t.processLogRecord(logRecord);
                }
            }

            @Override
            public void processStreamHeader(StreamHeaderRecord header) {
                for (LogRecordListener t : copy) {
                    t.processStreamHeader(header);
                }
            }
        };
    }

    /**
     * The byte-facing path: take the record's encoded form without downcasting to reach it.
     *
     * <p>M52.3, spec-binary-audit-encoding §6.1(2). A sink that ships records onward — to a queue, a
     * socket, a file — cares about bytes and not about whether the graph was configured with a text or
     * a binary log. Before this it had to downcast to a vendor record class, which is exactly what the
     * spec said a vendor sink should not have to do.
     *
     * <p>The default delegates to {@link LogRecord#encodeTo}, whose own default is the text form, so
     * every existing listener and every existing record keeps working untouched.
     */
    default void processLogRecord(LogRecord logRecord, java.io.OutputStream out)
            throws java.io.IOException {
        logRecord.encodeTo(out);
    }
}
